def parse_csv(content):
    """Parse CSV content into rows."""
    content = content.replace('\r\n', '\n').replace('\r', '\n')
    lines = content.strip().split('\n')
    if not lines:
        return [], []
    headers = lines[0].split(',')
    rows = []
    for line in lines[1:]:
        values = line.split(',')
        if len(values) >= len(headers):
            rows.append(dict(zip(headers, values)))
    return headers, rows

